#include "telemetry.h"
#include <esp_timer.h>
constexpr float DEG_TO_RAD_F=.01745329252f;
int16_t TelemetryManager::i16(const uint8_t*p){return int16_t(uint16_t(p[0])|(uint16_t(p[1])<<8));}uint16_t TelemetryManager::u16(const uint8_t*p){return uint16_t(p[0])|(uint16_t(p[1])<<8);}
void TelemetryManager::begin(){rateWindowMs_=millis();nextDueMs_=millis();}
void TelemetryManager::consume(const MspResponse&r){if(r.command==MspCommand::RAW_IMU&&r.length>=12){for(int i=0;i<3;i++){packet_.accelG[i]=i16(r.payload+2*i)/512.f;packet_.gyro[i]=i16(r.payload+6+2*i);}packet_.validity|=VALID_ACCEL|VALID_GYRO;}else if(r.command==MspCommand::MOTOR&&r.length>=8){for(int i=0;i<4;i++)packet_.motors[i]=u16(r.payload+2*i);packet_.validity|=VALID_MOTORS;}else if(r.command==MspCommand::ATTITUDE&&r.length>=6){packet_.attitudeRad[0]=i16(r.payload)/10.f*DEG_TO_RAD_F;packet_.attitudeRad[1]=i16(r.payload+2)/10.f*DEG_TO_RAD_F;packet_.attitudeRad[2]=i16(r.payload+4)*DEG_TO_RAD_F;packet_.validity|=VALID_ATTITUDE;}else if(r.command==MspCommand::ANALOG&&r.length>=1){packet_.batteryV=r.payload[0]/10.f;packet_.validity|=VALID_BATTERY;}}
void TelemetryManager::schedule(uint32_t nowMs){const uint8_t cycle=phase_++%40;uint8_t command=(cycle%2==0)?MspCommand::RAW_IMU:MspCommand::MOTOR;if(cycle%4==3)command=MspCommand::ATTITUDE;if(cycle==39)command=MspCommand::ANALOG;if(msp_.request(command))nextDueMs_=nowMs+5;}
void TelemetryManager::update(uint32_t nowMs){MspResponse response;if(msp_.takeResponse(response)){consume(response);samplesThisSecond_++;}if(!msp_.busy()&&int32_t(nowMs-nextDueMs_)>=0)schedule(nowMs);if(nowMs-rateWindowMs_>=1000){packet_.achievedHz=samplesThisSecond_*1000.f/(nowMs-rateWindowMs_);samplesThisSecond_=0;rateWindowMs_=nowMs;}if(!ready_&&nowMs-lastPublishMs_>=10){lastPublishMs_=nowMs;packet_.timestampUs=(uint64_t)esp_timer_get_time();packet_.sequence++;packet_.mspTimeouts=msp_.timeoutCount();ready_=true;}}
